using System.Text.Json; namespace VishalXOpt.Core.Helpers; public static class JsonFile { public static async Task<T?> ReadAsync<T>(string path,CancellationToken token=default)=>File.Exists(path)?JsonSerializer.Deserialize<T>(await File.ReadAllTextAsync(path,token)):default; public static async Task WriteAsync<T>(string path,T value,CancellationToken token=default){Directory.CreateDirectory(Path.GetDirectoryName(path)!); await File.WriteAllTextAsync(path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),token);} }